def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return tuple()
    parts = list(cmd)

    # Normalize the first path component (canonical form, backslashes, etc.)
    first = parts[0]
    first_norm = os.path.normpath(first)
    parts[0] = first_norm

    # Only apply extra processing on Windows
    if os.name == 'nt':
        # Only consider intervention if the first component is a file without an
        # executable extension (e.g. a .py script) and the file actually exists.
        ext = os.path.splitext(first_norm)[1].lower()
        if not ext and os.path.exists(first_norm):
            # Try to handle shebang lines (#!/usr/bin/python, etc.)
            try:
                with open(first_norm, 'rb') as fh:
                    line = fh.readline().decode(errors='ignore')
                if line.startswith('#!'):
                    # Break the shebang into the interpreter + optional args
                    parts_after = line[2:].strip().split()
                    if parts_after:
                        interpreter = parts_after[0]
                        # Resolve interpreter relative to PATH or use absolute path
                        if not os.path.isabs(interpreter):
                            interpreter = shutil.which(interpreter) or interpreter
                        shebang_args = tuple(parts_after[1:])
                        # Return a new command tuple that calls the interpreter
                        return (interpreter,) + shebang_args + (first_norm,) + tuple(parts[1:])
            except Exception:
                # If anything goes wrong, just pass on to the normal path below
                pass

            # If we didn't return above, prepend the current Python executable
            # so that the script runs under Python.
            return (sys.executable,) + tuple(parts)

    # For all platforms, quote any component that contains spaces so that
    # the command line is parsed correctly by CreateProcess/execve.
    def quote_if_needed(item: str) -> str:
        if ' ' in item and not (item.startswith('"') and item.endswith('"')):
            return f'"{item}"'
        return item

    return tuple(quote_if_needed(item) for item in parts)

