    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coord to array and validate dimensionality
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"coord must be array-like, got {type(coord)}") from exc

    if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must be a 1‑D iterable of length {len(self.edges)}, "
            f"got shape {coord_arr.shape}"
        )

    # Determine the bin index for each dimension
    idx = []
    for dim, edges_dim in enumerate(self.edges):
        # Find rightmost index where coord <= edge
        bin_idx = np.searchsorted(edges_dim, coord_arr[dim], side="right") - 1
        # Check bounds
        if bin_idx < 0 or bin_idx >= len(edges_dim) - 1:
            # Outside the histogram bounds – ignore this point
            return
        idx.append(bin_idx)

    # Ensure weight is a scalar numeric type
    if not np.isscalar(weight):
        raise ValueError(f"weight must be a scalar, got {type(weight)}")

    try:
        self.data[tuple(idx)] += weight
    except Exception as exc:
        raise RuntimeError(
            f"Failed to update histogram bin at indices {tuple(idx)}"
