    import tarfile
    import os

    try:
        resp = requests.get(url, stream=True, timeout=30)
        resp.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to download archive from {url}") from e

    try:
        if destination_path.exists():
            raise OSError(f"Destination path {destination_path} already exists")
        destination_path.mkdir(parents=True, exist_ok=False)
    except OSError as e:
        raise OSError(f"Could not create destination directory {destination_path}") from e

    tmp_file = None
    try:
        with tempfile.NamedTemporaryFile(suffix=".tar.gz", delete=False) as tmp:
            tmp_file = tmp.name
            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    tmp.write(chunk)
    except Exception as e:
        raise RuntimeError("Failed to write temporary archive file") from e

    try:
        with tarfile.open(tmp_file, mode="r:gz") as tar:
            tar.extractall(path=str(destination_path))
    except Exception as e:
        raise RuntimeError("Failed to extract archive") from e
    finally:
        if tmp_file and os.path.exists(tmp_file):
            os.remove(tmp_file)

    return destination_path

